import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const defaultFile = path.join(root, 'data', 'books.json');
const stylesheet = await readFile(path.join(root, 'public', 'styles.css'));

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function createBookStore(file = defaultFile) {
  let pending = Promise.resolve();

  async function readBooks() {
    try {
      const books = JSON.parse(await readFile(file, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Book file must contain an array');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }

  function update(change) {
    const result = pending.then(async () => {
      const books = await readBooks();
      const value = change(books);
      await mkdir(path.dirname(file), { recursive: true });
      const temporary = `${file}.${randomUUID()}.tmp`;
      try {
        await writeFile(temporary, JSON.stringify(books, null, 2) + '\n');
        await rename(temporary, file);
      } catch (error) {
        const { unlink } = await import('node:fs/promises');
        await unlink(temporary).catch(() => {});
        throw error;
      }
      return value;
    });
    pending = result.catch(() => {});
    return result;
  }

  return { readBooks, update };
}

function layout(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f8f7f2">
  <title>${escapeHtml(title)} · Booknotes</title>
  <link rel="stylesheet" href="/styles.css">
</head>
<body>
  <div class="site-shell">
    <header class="site-header">
      <a class="brand" href="/" aria-label="Booknotes home"><span class="brand-icon" aria-hidden="true">▤</span> booknotes<span class="brand-dot">.</span></a>
      <span class="header-caption">A little home for your reading</span>
    </header>
    <main>${content}</main>
    <footer class="site-footer">Your reading, one page at a time.</footer>
  </div>
</body>
</html>`;
}

function bookCard(book) {
  const url = `/books/${encodeURIComponent(book.id)}`;
  return `<article class="book-card">
    <div class="book-spine ${book.status === 'finished' ? 'book-spine-finished' : ''}" aria-hidden="true"><span>✦</span></div>
    <div class="book-card-content">
      <span class="eyebrow">${book.status === 'finished' ? 'Finished' : 'Currently reading'}</span>
      <h3><a href="${url}">${escapeHtml(book.title)}</a></h3>
      <p class="book-author">by ${escapeHtml(book.author)}</p>
      <div class="card-bottom"><a class="text-link" href="${url}">View notes <span aria-hidden="true">↗</span></a>${book.status === 'reading' ? `<form method="post" action="${url}/finish"><button class="small-button" type="submit">Mark finished</button></form>` : '<span class="finished-check">✓ Finished</span>'}</div>
    </div>
  </article>`;
}

function home(books, { error = '', values = {} } = {}) {
  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished');
  const fields = { title: values.title ?? '', author: values.author ?? '', notes: values.notes ?? '' };
  return layout('My books', `
    <section class="intro"><div><span class="eyebrow intro-eyebrow">YOUR PERSONAL BOOKSHELF</span><h1>Good books deserve<br><em>a place to stay.</em></h1><p>Keep track of the stories you’re in the middle of, the ones you’ve finished, and everything worth remembering.</p></div><div class="intro-mark" aria-hidden="true">✳</div></section>
    <div class="dashboard">
      <div class="shelf">
        <section class="book-section" aria-labelledby="reading-heading"><div class="section-heading"><div><span class="section-kicker">01 / IN PROGRESS</span><h2 id="reading-heading">Currently reading <span class="count">${reading.length}</span></h2></div></div>
        ${reading.length ? `<div class="book-list">${reading.map(bookCard).join('')}</div>` : '<div class="empty-state"><span class="empty-symbol" aria-hidden="true">✦</span><p>Nothing on your nightstand yet.</p><span>Add a book to get started.</span></div>'}</section>
        <section class="book-section finished-section" aria-labelledby="finished-heading"><div class="section-heading"><div><span class="section-kicker">02 / THE ARCHIVE</span><h2 id="finished-heading">Finished books <span class="count">${finished.length}</span></h2></div></div>
        ${finished.length ? `<div class="book-list">${finished.map(bookCard).join('')}</div>` : '<div class="empty-state"><span class="empty-symbol" aria-hidden="true">↗</span><p>Your finished shelf is waiting.</p><span>Books you finish will show up here.</span></div>'}</section>
      </div>
      <aside class="add-panel" id="add-book"><div class="panel-top"><span class="panel-icon" aria-hidden="true">＋</span><span class="section-kicker">MAKE SOME ROOM</span></div><h2>Add a book<span class="brand-dot">.</span></h2><p class="panel-description">What are you reading next? Add it to your shelf and jot down a thought or two.</p>
        ${error ? `<p class="form-error" role="alert">${escapeHtml(error)}</p>` : ''}
        <form method="post" action="/books" class="add-form">
          <label for="title">Book title <span aria-hidden="true">*</span></label><input id="title" name="title" type="text" maxlength="200" required placeholder="e.g. The Midnight Library" value="${escapeHtml(fields.title)}">
          <label for="author">Author <span aria-hidden="true">*</span></label><input id="author" name="author" type="text" maxlength="200" required placeholder="e.g. Matt Haig" value="${escapeHtml(fields.author)}">
          <label for="notes">Your notes <span class="optional">(optional)</span></label><textarea id="notes" name="notes" rows="5" maxlength="10000" placeholder="A quote, a thought, a reason you picked it up…">${escapeHtml(fields.notes)}</textarea>
          <button class="primary-button" type="submit">Add to my shelf <span aria-hidden="true">↗</span></button>
        </form><p class="panel-footnote">✳ &nbsp;Books are saved on this server.</p>
      </aside>
    </div>`);
}

function detail(book) {
  const finished = book.status === 'finished';
  return layout(book.title, `<div class="detail-wrap"><a href="/" class="back-link"><span aria-hidden="true">←</span> Back to my shelf</a>
    <article class="detail-card"><div class="detail-side"><div class="detail-book" aria-hidden="true"><span>✦</span></div><span class="section-kicker">A BOOK ON YOUR SHELF</span></div>
    <div class="detail-main"><span class="status-badge">${finished ? '✓ Finished' : '◌ Currently reading'}</span><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p><div class="detail-rule"></div><span class="section-kicker">YOUR NOTES</span><div class="notes">${book.notes ? escapeHtml(book.notes) : '<span class="no-notes">No notes for this book yet.</span>'}</div>
    ${finished ? '' : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit" class="primary-button detail-button">Mark as finished <span aria-hidden="true">✓</span></button></form>`}
    </div></article><p class="share-hint">To share this book, copy the link from your browser’s address bar.</p></div>`);
}

function sendHtml(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

async function readForm(req) {
  if (!req.headers['content-type']?.toLowerCase().startsWith('application/x-www-form-urlencoded')) {
    const error = new Error('Please submit the book form.');
    error.status = 415;
    throw error;
  }
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 30000) {
      const error = new Error('The form is too large.');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

export function createAppServer({ file = defaultFile } = {}) {
  const store = createBookStore(file);
  return http.createServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && pathname === '/styles.css') {
        res.writeHead(200, { 'Content-Type': 'text/css; charset=utf-8' });
        res.end(stylesheet);
        return;
      }
      if (req.method === 'GET' && pathname === '/') {
        sendHtml(res, 200, home(await store.readBooks()));
        return;
      }
      if (req.method === 'POST' && pathname === '/books') {
        const form = await readForm(req);
        const title = (form.get('title') ?? '').trim();
        const author = (form.get('author') ?? '').trim();
        const notes = (form.get('notes') ?? '').trim();
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          sendHtml(res, 400, home(await store.readBooks(), { error: 'Please enter a title and author (up to 200 characters each).', values: { title, author, notes } }));
          return;
        }
        const book = { id: randomUUID(), title, author, notes, status: 'reading' };
        await store.update((books) => books.unshift(book));
        res.writeHead(303, { Location: `/books/${book.id}` });
        res.end();
        return;
      }
      const match = /^\/books\/([0-9a-f-]{36})(\/finish)?$/.exec(pathname);
      if (match) {
        const [, id, finish] = match;
        if (req.method === 'GET' && !finish) {
          const book = (await store.readBooks()).find((item) => item.id === id);
          if (book) { sendHtml(res, 200, detail(book)); return; }
        }
        if (req.method === 'POST' && finish) {
          const found = await store.update((books) => {
            const book = books.find((item) => item.id === id);
            if (book) book.status = 'finished';
            return Boolean(book);
          });
          if (found) {
            res.writeHead(303, { Location: `/books/${id}` });
            res.end();
            return;
          }
        }
      }
      sendHtml(res, 404, layout('Not found', '<div class="not-found"><span class="eyebrow">PAGE NOT FOUND</span><h1>That book isn’t on this shelf.</h1><p>The link may be incorrect, or the book may no longer be here.</p><a class="primary-button" href="/">Return to my shelf <span aria-hidden="true">↗</span></a></div>'));
    } catch (error) {
      if (error.status) { sendHtml(res, error.status, layout('Unable to add book', `<div class="not-found"><h1>Couldn’t add that book.</h1><p>${escapeHtml(error.message)}</p><a href="/">Back to my shelf</a></div>`)); return; }
      console.error(error);
      sendHtml(res, 500, layout('Server error', '<div class="not-found"><h1>Something went wrong.</h1><p>We couldn’t load your books. Please try again.</p><a href="/">Back to my shelf</a></div>'));
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 3000);
  createAppServer({ file: process.env.BOOKS_FILE || defaultFile }).listen(port, () => {
    console.log(`Booknotes is running at http://localhost:${port}`);
  });
}
"}

