import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createAppServer } from './server.js';

async function start(file) {
  const server = createAppServer({ file });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return { server, base: `http://127.0.0.1:${server.address().port}` };
}

test('add, share, finish, and retain books across restarts', async () => {
  const dir = await mkdtemp(path.join(os.tmpdir(), 'booknotes-'));
  const file = path.join(dir, 'books.json');
  let app;
  try {
    app = await start(file);
    let response = await fetch(app.base);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /Nothing on your nightstand yet/);

    response = await fetch(`${app.base}/books`, {
      method: 'POST', body: new URLSearchParams({ title: '<The Story>', author: 'A & B', notes: 'A first line\nAnother line' }),
      redirect: 'manual',
